#include "stdafx.h"#include "HcdElementBase.h"struct SPTMR_P{#include "PrivateVars/PTMR.h"};class KPTMR : public KHcdElementBase  , protected SPTMR_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void OnFilledProjectSettings();  virtual void StepCalc( SStepCalcParams &params );private:  void Time();};static KHcdFactory _PTMR("PTMR", KPTMR::Create);IHcdElement *KPTMR::Create(){  return new KPTMR;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KPTMR, 10 )void KPTMR::InitParm(){#include "PrivateVars/PTMR.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KPTMR::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KPTMR::OnFilledProjectSettings(){  ASSD( !strcmp(Period, "Reset Cycle") );  Time();}void KPTMR::Time(){   time = CycleSecond + CycleMinute * 60.f + CycleHour * 60.f * 60.f;}void KPTMR::StepCalc( SStepCalcParams &params ){  if( RST )  {    Time();    return;      }  time -= params.dtS;  EVENT = 0;  if( time > 0 )    return;  Time();  EVENT = 1;}